/**
 * to toggle Visual Collapsible Group
 * - Input: Trigger element
 * - Input: Is animating flag
 */
function toggle(el, isAnimating) {
    var triggerGroup = el.closest('g');
    var childrenGroups = [];

    // [Rpt]: to climb DOM tree until we locate the adjacent content groups
    while (triggerGroup && triggerGroup.tagName.toLowerCase() === 'g') {
        var sibling = triggerGroup.nextElementSibling;
        var foundAny = false;
        // [Rpt]: to check siblings for 'g' tags
        while (sibling) {
            // [Opt]: to handle tag Name of sibling equals = g
            if (sibling.tagName.toLowerCase() === 'g') {
                childrenGroups.push(sibling);
                foundAny = true;
            }
            sibling = sibling.nextElementSibling;
        }
        // [Esc]: to stop climbing if we found sibling groups
        if (foundAny) break;
        // to climb out if trapped in an inner wrapper
        triggerGroup = triggerGroup.parentElement;
        // [Esc]: to stop at major structural graph IDs
        if (triggerGroup && triggerGroup.id && triggerGroup.id.indexOf('graph') !== -1) {
            break;
        }
    }

    var hasChildrenGroup = (childrenGroups.length > 0);
    var isHiding = false;

    // [Alt "(hasChildrenGroup)"]: to apply when hasChildrenGroup
    if (hasChildrenGroup) {
        isHiding = (childrenGroups[0].style.display !== 'none');
        // [Alt "not (hasChildrenGroup)"]: to apply when not (hasChildrenGroup
    } else {
        isHiding = (el.textContent === '-');
    }

    var newDisplay = isHiding ? 'none' : 'inline';
    var newText = isHiding ? '+' : '-';

    // [Opt]: to apply when hasChildrenGroup)
    if (hasChildrenGroup) {
        childrenGroups.forEach(function (group) {
            // [Opt]: to handle is Hiding
            if (isHiding) {
                var nestedTriggers = group.querySelectorAll('.collapsible-trigger');
                nestedTriggers.forEach(function (trigger) {
                    // [Opt]: to handle text Content of trigger equals = -
                    if (trigger.textContent === '-') {
                        toggle(trigger, isAnimating);
                    }
                });
            }
            group.style.display = newDisplay;
        });
    }

    el.textContent = newText;

    var targetsStr = el.getAttribute('data-targets');
    // [Opt]: to apply when targetsStr) {
    if (targetsStr) {
        var targetIds = targetsStr.split(',');
        targetIds.forEach(function (id) {
            var target = document.getElementById(id);
            // [Opt]: to handle target
            if (target) {
                var count = parseInt(target.getAttribute('data-ref-count') || '1');
                count += (isHiding ? -1 : 1);
                target.setAttribute('data-ref-count', count);

                // [Alt]: to handle !is Animating !is Hiding
                if (!isAnimating && !isHiding) {
                    target.style.display = (count > 0) ? 'inline' : 'none';
                    // [Alt]: to handle !is Animating is Hiding
                } else if (!isAnimating && isHiding) {
                    target.style.display = (count > 0) ? 'inline' : 'none';
                }
            }
        });
    }
}

