    });
    var isGraphviz = nodeGroup.classList.contains('node') || nodeGroup.classList.contains('edge') || nodeGroup.querySelector('.node') !== null || nodeGroup.querySelector('.edge') !== null;

    function markFallbackShape(activate) {
        var shape = nodeGroup.querySelector('rect, polygon, polyline, path, circle, ellipse');
        // [Esc]: to handle !shape
