    if (e.key === 'Escape' && isAnimationActive) {
        var animWand = document.getElementById('animWand');
        if (animWand) animWand.textContent = '\u{1FA84}';
        stopAnimation();
        var popup = document.getElementById('nabu-animation-popup');
        if (popup) popup.style.display = 'none';
    }
});
